using TMPro;
using UnityEngine;

/// <summary>
/// Colours and fonts for the military UI. Font assets are generated by
/// Tools > FPS > Setup UI Fonts into
/// Assets/UI/Resources/Fonts & Materials, the folder TMP also searches for <font="..."> tags.
/// </summary>
public static class UITheme {

    public const string FontFolder = "Fonts & Materials/";

    public static readonly Color Ink = Hex(0xECEAE3);
    public static readonly Color Mute = Hex(0x8E918A);
    public static readonly Color Dim = Hex(0x5D605A);
    public static readonly Color Amber = Hex(0xE3A72F);
    public static readonly Color Olive = Hex(0x8DB255);
    public static readonly Color Red = Hex(0xD8432E);
    public static readonly Color Victim = Hex(0xE2867A);
    public static readonly Color Panel = new Color(0.047f, 0.055f, 0.047f, 0.70f);
    public static readonly Color PanelSolid = new Color(0.047f, 0.055f, 0.047f, 0.90f);
    public static readonly Color Line = new Color(0.925f, 0.918f, 0.89f, 0.14f);
    public static readonly Color Line2 = new Color(0.925f, 0.918f, 0.89f, 0.28f);
    public static readonly Color Field = new Color(0f, 0f, 0f, 0.45f);
    public static readonly Color AmberWash = new Color(0.89f, 0.655f, 0.184f, 0.14f);

    private static TMP_FontAsset cond, condBold, condMedium, body, bodyBold;
    private static Font legacy;
    private static TMP_FontAsset chinese;

    /// <summary>Full Simplified Chinese glyph coverage; shared by every UI font.</summary>
    public static TMP_FontAsset ChineseFont {
        get {
            if (chinese == null) {
                Font source = Resources.Load<Font>(FontFolder + "NotoSansCJKsc-Regular");
                if (source != null) chinese = TMP_FontAsset.CreateFontAsset(source);
            }
            return chinese;
        }
    }

    /// <summary>Barlow Condensed SemiBold: headings and buttons.</summary>
    public static TMP_FontAsset Cond => Load(ref cond, "Cond-SemiBold");
    /// <summary>Barlow Condensed Bold: big numbers.</summary>
    public static TMP_FontAsset CondBold => Load(ref condBold, "Cond-Bold");
    /// <summary>Barlow Condensed Medium: small spaced-out labels.</summary>
    public static TMP_FontAsset CondMedium => Load(ref condMedium, "Cond-Medium");
    /// <summary>Noto Sans KR Regular: body text, Korean.</summary>
    public static TMP_FontAsset Body => Load(ref body, "Body-Regular");
    /// <summary>Noto Sans KR Bold.</summary>
    public static TMP_FontAsset BodyBold => Load(ref bodyBold, "Body-Bold");

    /// <summary>Korean-capable font for legacy uGUI Text (world-space name tags).</summary>
    public static Font LegacyFont {
        get {
            if (legacy == null) {
                legacy = Resources.Load<Font>(FontFolder + "NotoSansKR-Bold");
            }
            return legacy;
        }
    }

    /// <summary>Player-supplied text made safe to embed in TMP rich text.</summary>
    public static string Safe(string s) {
        return string.IsNullOrEmpty(s) ? "?" : s.Replace("<", "\u2039").Replace(">", "\u203A");
    }

    public static Color WithAlpha(Color c, float a) {
        c.a = a;
        return c;
    }

    private static TMP_FontAsset Load(ref TMP_FontAsset cache, string name) {
        if (cache == null) {
            TMP_FontAsset source = Resources.Load<TMP_FontAsset>(FontFolder + name);
            if (source == null) {
                Debug.LogWarning("UI font '" + name + "' missing; run Tools > FPS > Setup UI Fonts.");
                source = TMP_Settings.defaultFontAsset;
            }
            // A shallow asset clone would share the texture with a second glyph packer and corrupt its glyphs.
            // Create an independent atlas and material; saved font assets remain available for TMP rich-text tags.
            if (source != null && source.sourceFontFile != null) {
                cache = TMP_FontAsset.CreateFontAsset(source.sourceFontFile, (int)source.faceInfo.pointSize,
                    source.atlasPadding, source.atlasRenderMode, source.atlasWidth, source.atlasHeight,
                    AtlasPopulationMode.Dynamic, true);
                cache.name = source.name;
                cache.fallbackFontAssetTable = new System.Collections.Generic.List<TMP_FontAsset>();
                if (name.StartsWith("Cond-")) cache.fallbackFontAssetTable.Add(name == "Cond-Medium" ? Body : BodyBold);
            } else {
                cache = source;
                return cache;
            }
        }
        TMP_FontAsset fallback = ChineseFont;
        if (cache != null && fallback != null && !cache.fallbackFontAssetTable.Contains(fallback))
            cache.fallbackFontAssetTable.Add(fallback);
        return cache;
    }

    private static Color Hex(int rgb) {
        return new Color(((rgb >> 16) & 0xFF) / 255f, ((rgb >> 8) & 0xFF) / 255f, (rgb & 0xFF) / 255f, 1f);
    }

}
